// Physical Designs page: places the pieces in a collage, alternating right / left at
// different sizes, each tucked part-way down the one before (from the page design).
// The pieces themselves are generated by scripts/build.js from projects marked "section: physical".
(function () {
  // Positions from the design, as a share of the content width (x, width), repeating every 4 pieces.
  // Odd pieces start halfway down the piece before; even pieces start just below it.
  var PATTERN = [
    { x: 42.5, w: 57.5 },   // right, large
    { x: 0,    w: 34.5 },   // left, small — tucked halfway down the one before
    { x: 64.6, w: 34   },   // right, small — just below the one before
    { x: 0,    w: 48   }    // left, medium — tucked halfway down the one before
  ];
  var GAP = 3;              // space below a piece before an "even" piece starts (% of width)
  var root = document.getElementById('collage');
  if (!root) return;
  var pieces = [].slice.call(root.querySelectorAll('.pd-piece'));
  function layout() {
    if (window.matchMedia('(max-width: 720px)').matches) return;
    var W = root.clientWidth, y = 0, prev = null, bottom = 0;
    pieces.forEach(function (el, i) {
      var p = PATTERN[i % PATTERN.length];
      var img = el.querySelector('img');
      var ratio = img.getAttribute('height') / img.getAttribute('width');
      var w = p.w / 100 * W, h = w * ratio;
      if (prev) y = (i % 2) ? prev.y + prev.h * 0.5 : prev.y + prev.h + GAP / 100 * W;
      el.style.left = (p.x / 100 * W) + 'px';
      el.style.top = y + 'px';
      el.style.width = w + 'px';
      el.querySelector('.pd-piece__img').style.height = h + 'px';
      prev = { y: y, h: h };
      bottom = Math.max(bottom, y + h);
    });
    root.style.height = (bottom + 40) + 'px';
  }
  layout();
  window.addEventListener('resize', layout);
})();
